package io.scenariomesh.config;
import java.nio.file.Path;import java.time.Duration;import java.util.*;
public final class ConfigResolver{public ScenarioMeshConfig resolve(Path projectDirectory,Path buildDirectory,Map<String,String> props,Map<String,String> env){ScenarioMeshConfig d=ScenarioMeshConfig.defaults(buildDirectory);return new ScenarioMeshConfig(bool(v("scenariomesh.enabled",props,env),d.enabled()),integer(v("scenariomesh.workers",props,env),d.workerCount()),duration(v("scenariomesh.discovery.timeout",props,env),d.discoveryTimeout()),duration(v("scenariomesh.worker.startupTimeout",props,env),d.workerStartupTimeout()),duration(v("scenariomesh.worker.shutdownTimeout",props,env),d.workerShutdownTimeout()),path(v("scenariomesh.reporting.directory",props,env),projectDirectory,d.reportingDirectory()),list(v("scenariomesh.worker.jvmArgs",props,env),d.workerJvmArgs()));}private String v(String k,Map<String,String> p,Map<String,String> e){String x=p.get(k);return x!=null?x:e.get(k.toUpperCase(Locale.ROOT).replace('.','_'));}private boolean bool(String v,boolean d){return v==null?d:Boolean.parseBoolean(v);}private int integer(String v,int d){return v==null?d:Integer.parseInt(v);}private Duration duration(String v,Duration d){return v==null?d:Duration.parse(v);}private Path path(String v,Path base,Path d){if(v==null)return d.toAbsolutePath().normalize();Path p=Path.of(v);return (p.isAbsolute()?p:base.resolve(p)).toAbsolutePath().normalize();}private List<String> list(String v,List<String>d){if(v==null||v.isBlank())return d;return Arrays.stream(v.split("\\s+")).filter(s->!s.isBlank()).toList();}}
